import json, math
OUT = '/home/user/wt-m22/content/math'
INK = '#0f172a'; ACC = '#0f6e56'

def mk(opts, key, tags=None):
    tags = tags or {}
    ids = 'abcd'
    out = []
    for i, t in enumerate(opts):
        o = {'id': ids[i], 'text': t}
        if t in tags and i != key:
            o['misconceptionTag'] = tags[t]
        out.append(o)
    return out, ids[key]

def Q(prompt, opts, key, expl, diff, comps, tags=None):
    o, c = mk(opts, key, tags)
    return {'prompt': prompt, 'options': o, 'correctOption': c, 'explanation': expl, 'difficulty': diff, 'competencies': comps}

# ---------- SVG helpers ----------
def f(x): return ('%.1f' % x).rstrip('0').rstrip('.')
def svg_tri(title, show_o=False, show_ef=False, show_k=False, right=False, ef_acc=True):
    s = 4.2
    B = (24, 200); C = (276, 200); A = (150, 32); O = (150, 200)
    E = (A[0] + .3 * (B[0] - A[0]), A[1] + .3 * (B[1] - A[1]))
    F = (A[0] + .3 * (C[0] - A[0]), E[1]); K = (150, E[1])
    p = []
    p.append('<polygon points="%s,%s %s,%s %s,%s" fill="none" stroke="%s" stroke-width="2.2" stroke-linejoin="round"/>' % (f(A[0]), f(A[1]), f(B[0]), f(B[1]), f(C[0]), f(C[1]), INK))
    pts = [('A', A, (0, -9)), ('B', B, (-12, 8)), ('C', C, (12, 8))]
    if show_o:
        p.append('<path d="M150 32 L150 200" fill="none" stroke="%s" stroke-width="1.8" stroke-dasharray="5 4"/>' % INK)
        pts.append(('O', O, (0, 17)))
        if right:
            p.append('<path d="M150 190 L160 190 L160 200" fill="none" stroke="%s" stroke-width="1.6"/>' % INK)
    if show_ef:
        p.append('<path d="M%s %s L%s %s" fill="none" stroke="%s" stroke-width="3" stroke-linecap="round"/>' % (f(E[0]), f(E[1]), f(F[0]), f(F[1]), ACC))
        pts += [('E', E, (-12, 4)), ('F', F, (12, 4))]
        if show_k:
            pts.append(('K', K, (11, -7)))
    dots = ''.join('<circle cx="%s" cy="%s" r="3.6" fill="%s"/>' % (f(P[0]), f(P[1]), INK) for _, P, _ in pts)
    labels = ''.join('<text x="%s" y="%s" text-anchor="middle" fill="%s" font-size="15">%s</text>' % (f(P[0] + d[0]), f(P[1] + d[1] + 5), INK, n) for n, P, d in pts)
    return ('<svg viewBox="0 0 300 232"><title>%s</title>' % title + ''.join(p) + dots +
            '<g font-weight="700" direction="ltr" unicode-bidi="isolate" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">' + labels + '</g></svg>')

def svg_poly(title):
    pts = [(300, 0), (500, 50), (700, 120), (900, 150), (1100, 190), (1300, 200)]
    X = lambda x: 44 + (x - 200) * 0.235
    Y = lambda v: 190 - v * 0.75
    p = []
    for x in range(300, 1400, 100):
        p.append('<path d="M%s %s L%s %s" stroke="#cbd5e1" stroke-width="0.8" fill="none"/>' % (f(X(x)), f(Y(0)), f(X(x)), f(Y(220))))
    for v in range(0, 221, 20):
        p.append('<path d="M%s %s L%s %s" stroke="#cbd5e1" stroke-width="0.8" fill="none"/>' % (f(X(200)), f(Y(v)), f(X(1400)), f(Y(v))))
    p.append('<path d="M%s %s L%s %s M%s %s L%s %s" stroke="%s" stroke-width="1.8" fill="none"/>' % (f(X(200)), f(Y(0)), f(X(1400)), f(Y(0)), f(X(200)), f(Y(0)), f(X(200)), f(Y(220)), INK))
    line = ' '.join('%s,%s' % (f(X(x)), f(Y(v))) for x, v in pts)
    p.append('<polyline points="%s" fill="none" stroke="%s" stroke-width="2.6" stroke-linejoin="round"/>' % (line, ACC))
    p += ['<circle cx="%s" cy="%s" r="3.4" fill="%s"/>' % (f(X(x)), f(Y(v)), ACC) for x, v in pts]
    lab = ''
    for x in range(300, 1400, 200):
        lab += '<text x="%s" y="%s" text-anchor="middle" font-size="10" fill="%s">%d</text>' % (f(X(x)), f(Y(0) + 13), INK, x)
    for v in (0, 50, 100, 150, 200):
        lab += '<text x="%s" y="%s" text-anchor="end" font-size="10" fill="%s">%d</text>' % (f(X(200) - 4), f(Y(v) + 3.5), INK, v)
    return '<svg viewBox="0 0 330 212"><title>%s</title>' % title + ''.join(p) + '<g direction="ltr" unicode-bidi="isolate">' + lab + '</g></svg>'

def svg_table(title):
    cls = ['[300 ; 500[', '[500 ; 700[', '[700 ; 900[', '[900 ; 1100[', '[1100 ; 1300[']
    ef = [50, 70, 30, 40, 10]
    w = 62; x0 = 10; y0 = 10; h = 30
    p = []
    for r in range(2):
        for i in range(5):
            x = x0 + i * w; y = y0 + r * h
            p.append('<rect x="%d" y="%d" width="%d" height="%d" fill="%s" stroke="%s" stroke-width="1.2"/>' % (x, y, w, h, '#e6f4ef' if r == 0 else 'none', INK))
    t = ''
    for i in range(5):
        cx = x0 + i * w + w / 2
        t += '<text x="%s" y="%s" text-anchor="middle" font-size="10.5" fill="%s">%s</text>' % (f(cx), y0 + 19, INK, cls[i])
        t += '<text x="%s" y="%s" text-anchor="middle" font-size="13" fill="%s">%d</text>' % (f(cx), y0 + h + 20, INK, ef[i])
    return '<svg viewBox="0 0 330 80"><title>%s</title>' % title + ''.join(p) + '<g direction="ltr" unicode-bidi="isolate" font-weight="700">' + t + '</g></svg>'

def hdr(title, diff, num):
    mode, xp, c = {2: ('practice', 75, 15), 3: ('boss', 120, 30)}[diff]
    return {'title': title, 'difficulty': diff, 'mode': mode, 'xpReward': xp, 'rewardCoins': c, 'displayOrder': num}

def save(rel, d):
    with open(OUT + '/' + rel, 'w', encoding='utf-8') as fh:
        json.dump(d, fh, ensure_ascii=False, indent=2)
        fh.write('\n')

